// src/sections/update-usage.ts
async function updateUsage(sectionToken, inputs) {
  const log3 = new LogTask(sectionToken);
  log3.start();
  const actionName = `${inputs.owner}/${inputs.repo}`;
  log3.info(`Action name: ${actionName}`);
  const versionString = getCurrentVersionString(inputs);
  log3.info(`Version string: ${versionString}`);
  const actionReference = `${actionName}@${versionString}`;
  const indent = "    # ";
  const content = [];
  content.push("```yaml", `- uses: ${actionReference}`, "  with:");
  const inp = inputs.action.inputs;
  let firstInput = true;
  const descriptionPromises = {};
  if (inp) {
    for (const key of Object.keys(inp)) {
      const input = inp[key];
      if (input !== void 0) {
        descriptionPromises[key] = wrapDescription(`Description: ${input.description}`, [], indent);
      }
    }
    const descriptions = {};
    const kvArray = await Promise.all(
      Object.keys(descriptionPromises).map(async (key) => {
        return { key, value: await descriptionPromises[key] };
      })
    );
    for (const e of kvArray) {
      descriptions[e.key] = e.value;
      log3.debug(`${e.key}: ${descriptions[e.key].join("\n")}`);
    }
    for (const key of Object.keys(inp)) {
      const input = inp[key];
      if (input !== void 0) {
        if (!firstInput) {
          content.push("");
        }
        content.push(...descriptions[key]);
        if (input.default !== void 0) {
          content.push(`${indent}Default: ${input.default}`);
        }
        content.push(`    ${key}: ''`);
        firstInput = false;
      }
    }
  }
  content.push("```\n");
  inputs.readmeEditor.updateSection(sectionToken, content);
  log3.success();
  const ret = {};
  ret[sectionToken] = content.join("\n");
  return ret;
}

// src/sections/index.ts
var log2 = new LogTask("updateSection");
async function updateSection(section, inputs) {
  const [startToken, stopToken] = inputs.readmeEditor.getTokenIndexes(section);
  if (startToken === -1 || stopToken === -1) {
    return {};
  }
  switch (section) {
    case "branding": {
      return await updateBranding(section, inputs);
    }
    case "badges": {
      return await updateBadges(section, inputs);
    }
    case "usage": {
      return await updateUsage(section, inputs);
    }
    case "title": {
      return await updateTitle(section, inputs);
    }
    case "description": {
      return await updateDescription(section, inputs);
    }
    case "inputs": {
      return await updateInputs(section, inputs);
    }
    case "outputs": {
      return await updateOutputs(section, inputs);
    }
    case "contents": {
      return await updateContents(section, inputs);
    }
    default: {
      log2.debug(`unknown section found <!-- start ${section} -->. No updates were made.`);
      return {};
    }
  }
}

// src/readme-generator.ts
var ReadmeGenerator = class {
  /**
   * The Inputs instance.
   */
  inputs;
  /**
   * The Logger instance.
   */
  log;
  /**
   * Initializes the ReadmeGenerator.
   *
   * @param inputs - The Inputs instance
   * @param log - The Logger instance
   */
  constructor(inputs, log3) {
    this.inputs = inputs;
    this.log = log3;
  }
  /**
   * Updates the README sections.
   *
   * @param sections - The sections array
   * @returns Promise array of section KV objects
   */
  updateSections(sections) {
    const promises2 = [];
    for (const section of sections) {
      promises2.push(updateSection(section, this.inputs));
    }
    return promises2;
  }
  /**
   * Resolves the section update promises.
   *
   * @param promises - The promise array
   * @returns Promise resolving to combined sections KV
   */
  async resolveUpdates(promises2) {
    this.log.debug("Resolving updates");
    const results = await Promise.all(promises2);
    const sections = {};
    for (const result of results) {
      Object.assign(sections, result);
    }
    return sections;
  }
  /**
   * Outputs the sections KV to GitHub output.
   *
   * @param sections - The sections KV
   */
  outputSections(sections) {
    if (process.env.GITHUB_ACTIONS) {
      this.log.debug("Outputting sections");
      core4.setOutput("sections", JSON.stringify(sections, null, 2));
    } else {
      this.log.debug("Not outputting sections");
    }
  }
  /**
   * Generates the README documentation.
   *
   * @returns Promise resolving when done
   */
  async generate(providedSections = this.inputs.sections) {
    const sectionPromises = this.updateSections(providedSections);
    const sections = await this.resolveUpdates(sectionPromises);
    this.outputSections(sections);
    return this.inputs.readmeEditor.dumpToFile();
  }
};

