import { promises as fsPromises } from "node:fs";
import path6 from "node:path";
var GHActionDocsConfig = class {
  owner;
  repo;
  title_prefix;
  title;
  paths;
  branding_svg_path;
  versioning;
  prettier;
  /**
   * Loads the configuration from the provided `Inputs` object.
   * @param {Inputs} inputs - The `Inputs` object containing the configuration values.
   */
  loadInputs(inputs) {
    const config = inputs.config.get();
    this.owner = config.owner;
    this.repo = config.repo;
    this.title_prefix = config.title_prefix;
    this.title = config.title;
    this.paths = config.paths;
    this.branding_svg_path = config.branding_svg_path;
    this.versioning = config.versioning;
    this.prettier = config.prettier;
  }
  /**
   * Saves the configuration to a file. If the file exists, it will be overwritten.
   * @param {string} configPath - The path to the configuration file.
   */
  async save(configPath) {
    const log3 = new LogTask("config:save");
    const directory = path6.dirname(configPath);
    try {
      await fsPromises.mkdir(directory, { recursive: true });
    } catch (error2) {
      log3.error(`Error creating directory: ${directory}.`);
      throw error2;
    }
    try {
      await fsPromises.writeFile(configPath, JSON.stringify(this, null, 2));
      log3.info(`Config file written to: ${configPath}`);
    } catch (error2) {
      log3.error(`Error writing config file: ${configPath}.`);
      throw error2;
    }
  }
};

// src/save.ts
function save(inputs, log3) {
  const docsConfig = new GHActionDocsConfig();
  docsConfig.loadInputs(inputs);
  if (inputs.config.get().save === true) {
    try {
      docsConfig.save(inputs.configPath);
    } catch (error2) {
      log3.error(`${error2}`);
    }
  }
}

